import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, dot, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const typography = config.intent?.visualSpec?.typography ?? {
    hero: { fontSize: 124, letterSpacing: -0.015 },
    kicker: { fontSize: 18, letterSpacing: 0.12 },
    body: { fontSize: 26, letterSpacing: 0 },
    caption: { fontSize: 18, letterSpacing: 0.08 },
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findByRole = (role, fallback) => {
    const found = items.filter((i) => i.role === role);
    return found.length ? found : fallback;
  };

  const kickerItem = findByRole('kicker', [{ text: 'NOVA ATELIER / JOURNAL' }])[0];
  const heroItems = findByRole('hero', [{ text: 'PRECISION IS' }, { text: 'A HABIT.' }]);
  const bodyItem = findByRole(
    'body',
    [{ text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.' }]
  )[0];
  const captionItem = findByRole('caption', [{ text: 'ISSUE 12 / JULY 2026' }])[0];

  const root = new Group();
  root.name = 'editorial-oversized-type';

  // ---------------------------------------------------------------
  // Backdrop plate: 7 x 5.5 engineered gradient + subtle grain
  // ---------------------------------------------------------------
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const uvNode = uv();
  const gradient = mix(color(colors.background), color(colors.surface), uvNode.y);
  const grainSeed = uvNode.mul(1000.0);
  const noise = fract(sin(dot(grainSeed, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = noise.sub(0.5).mul(0.015);
  plateMat.colorNode = gradient.add(grain);

  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.05);
  root.add(plate);

  // ---------------------------------------------------------------
  // Text blocks
  // ---------------------------------------------------------------
  const LEFT_X = -1.5;
  const disposables = [];
  const trackDisposal = (obj) => {
    obj.traverse((child) => {
      if (child.geometry) disposables.push(child.geometry);
      if (child.material) disposables.push(child.material);
    });
  };

  // Kicker
  const kickerText = ctx.fontAtlas.createText((kickerItem?.text ?? '').toUpperCase(), {
    fontSize: kickerItem?.typography?.fontSize ?? typography.kicker.fontSize,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: (typography.kicker.letterSpacing ?? 0.12) * (typography.kicker.fontSize ?? 18),
  });
  kickerText.position.set(LEFT_X, 1.7, 0.01);
  root.add(kickerText);
  trackDisposal(kickerText);

  // Hero lines (with letterpress shadow duplicates)
  const heroYs = [0.9, 0.25];
  const heroGroups = [];
  heroItems.slice(0, 2).forEach((item, i) => {
    const fontSize = item?.typography?.fontSize ?? typography.hero.fontSize;
    const letterSpacingPx = (typography.hero.letterSpacing ?? -0.015) * fontSize;

    const shadow = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colors.ink,
      align: 'left',
      letterSpacingPx,
    });
    shadow.position.set(LEFT_X, heroYs[i], -0.02);
    root.add(shadow);
    trackDisposal(shadow);

    const main = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colors.paper,
      align: 'left',
      letterSpacingPx,
    });
    main.position.set(LEFT_X, heroYs[i], 0.02);
    root.add(main);
    trackDisposal(main);

    heroGroups.push({ shadow, main, targetY: heroYs[i] });
  });

  // Accent underline rule (emissive, pivoted at left edge for scaleX draw-in)
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  ruleGeo.translate(1.1, 0, 0);
  const ruleMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  ruleMat.colorNode = color(colors.accent);
  ruleMat.emissiveNode = color(colors.accent).mul(1.2);
  ruleMat.roughness = 0.55;
  ruleMat.metalness = 0.2;
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(LEFT_X, -0.15, 0.015);
  rule.scale.x = 0;
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // Body paragraph
  const bodyText = ctx.fontAtlas.createText(bodyItem?.text ?? '', {
    fontSize: bodyItem?.typography?.fontSize ?? typography.body.fontSize,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 4.5 * 200,
    letterSpacingPx: (typography.body.letterSpacing ?? 0) * (typography.body.fontSize ?? 26),
  });
  bodyText.position.set(LEFT_X, -0.8, 0.01);
  root.add(bodyText);
  trackDisposal(bodyText);

  // Caption
  const captionText = ctx.fontAtlas.createText(captionItem?.text ?? '', {
    fontSize: captionItem?.typography?.fontSize ?? typography.caption.fontSize,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: (typography.caption.letterSpacing ?? 0.08) * (typography.caption.fontSize ?? 18),
  });
  captionText.position.set(LEFT_X, -1.9, 0.01);
  root.add(captionText);
  trackDisposal(captionText);

  // ---------------------------------------------------------------
  // Motion: rise-in per block, top to bottom, 80ms stagger
  // ---------------------------------------------------------------
  const timelines = [];

  function riseIn(obj, targetY, delay) {
    obj.position.y = targetY + 0.4;
    const mats = [];
    obj.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
        mats.push(child.material);
      }
    });
    const tl = gsap.timeline({ delay });
    tl.to(obj.position, { y: targetY, duration: 0.7, ease: 'power3.out' }, 0);
    mats.forEach((m) => {
      tl.to(m, { opacity: 1, duration: 0.7, ease: 'power3.out' }, 0);
    });
    timelines.push(tl);
    return tl;
  }

  let stagger = 0;
  riseIn(kickerText, 1.7, stagger);
  stagger += 0.08;

  heroGroups.forEach((hg) => {
    riseIn(hg.shadow, hg.targetY, stagger);
    riseIn(hg.main, hg.targetY, stagger);
    stagger += 0.08;
  });

  riseIn(bodyText, -0.8, stagger);
  stagger += 0.08;
  riseIn(captionText, -1.9, stagger);

  // Rule draws in after hero lands
  const ruleDelay = 0.08 + heroGroups.length * 0.08 + 0.7;
  const ruleTl = gsap.timeline({ delay: ruleDelay });
  ruleTl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power2.out' });
  timelines.push(ruleTl);

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    disposables.length = 0;
  };

  return root;
}
